      "Bir müşteri yalnızca tek çalışanı tanıyorsa ve o çalışan müsait değilse süreç aksar. CRM sayesinde notlar, görevler ve geçmiş temas bilgileri ekip genelinde erişilebilir olur. Böylece müşteri deneyimi kişiye değil sisteme bağlı hale gelir.",
