      "2. Optimize keywords with Quality Score below 7",
      "3. Test Smart Bidding in one campaign (Target ROAS)",
      "4. Test the speed of your highest traffic landing page (PageSpeed Insights)",
      "5. Replace your lowest performing ad copy with a new one",
      "",
