    excerptEn: "Get your product pages to Google's top ranking. Keyword optimization, schema markup and conversion-focused SEO techniques.",
    category: "ecommerce",
    categoryLabel: "E-Ticaret",
    categoryLabelEn: "E-Commerce",
    image: 86,
    date: "2026-03-27",
    readTime: "14 dk",
